    <div class="flex flex-col gap-3 rounded-lg border border-border bg-surface-alt p-4 sm:flex-row sm:items-center"><div class="flex flex-wrap gap-2"><button type="button" data-reset-positions class="rounded-md border border-border bg-surface px-4 py-2 text-sm font-medium text-text shadow-sm transition hover:bg-surface-alt focus:outline-none focus:ring-2 focus:ring-primary/40">Reset positions</button><button type="button" data-toggle-labels style="width: 150px; min-width: 150px; max-width: 150px;" class="w-36 flex-none justify-center rounded-md border border-primary/30 bg-primary/5 px-4 py-2 text-sm font-medium text-primary-dark shadow-sm transition hover:bg-primary/10 focus:outline-none focus:ring-2 focus:ring-primary/40">Show labels: ON</button></div><p class="flex-1 text-sm leading-relaxed text-text-muted">Amount in words often needs two lines on real cheques. Drag the bottom edge of the amount-in-words box to make it taller.</p></div>
</div>
@push('scripts')
<script>
document.addEventListener('DOMContentLoaded', () => document.querySelectorAll('[data-alignment-tool]').forEach((root) => {
 const canvas=root.querySelector('[data-alignment-canvas]'), input=root.querySelector('[data-field-positions]'), defaults=@json((new \App\Models\ChequeTemplate)->defaultFieldPositions());
 const labels={payee:'Pay to',amount_digits:'Amount',amount_words_1:'Amount in words (line 1)',amount_words_2:'Amount in words (line 2)',date:'Date',memo:'Memo / Reference'};
 const snap=v=>Math.round(v*2)/2, clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 const setReady=ready=>{canvas.dataset.imageReady=ready?'true':'false';root.querySelectorAll('.field-box').forEach(b=>b.classList.remove('hidden'));};
 const form=root.closest('form'), widthInput=form?.querySelector('[name=width_mm]'), heightInput=form?.querySelector('[name=height_mm]');
 const updateRatio=()=>{if(widthInput&&heightInput)canvas.style.aspectRatio=`${widthInput.value||203} / ${heightInput.value||90}`;};
 widthInput?.addEventListener('input',updateRatio);heightInput?.addEventListener('input',updateRatio);updateRatio();
 const fileInput=form?.querySelector('[data-background-input]'), zone=form?.querySelector('[data-upload-zone]');
 const showFile=file=>{if(!file)return;const reader=new FileReader();reader.onload=()=>{let image=canvas.querySelector('[data-canvas-image]');if(!image){image=document.createElement('img');image.dataset.canvasImage='';image.className='absolute inset-0 h-full w-full object-fill';canvas.querySelector('[data-canvas-placeholder]')?.remove();canvas.prepend(image);}image.src=reader.result;setReady(true);syncCheckboxesToCanvas();const preview=zone?.querySelector('[data-upload-preview]');if(preview){preview.classList.remove('hidden');preview.classList.add('flex');preview.textContent=file.name;}};reader.readAsDataURL(file);};
 zone?.querySelector('[data-upload-trigger]')?.addEventListener('click',()=>fileInput?.click());fileInput?.addEventListener('change',e=>showFile(e.target.files?.[0]));zone?.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('border-primary');});zone?.addEventListener('dragleave',()=>zone.classList.remove('border-primary'));zone?.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('border-primary');const file=e.dataTransfer.files?.[0];if(file){const transfer=new DataTransfer();transfer.items.add(file);fileInput.files=transfer.files;showFile(file);}});
 const read=b=>({x:snap(parseFloat(b.style.left)),y:snap(parseFloat(b.style.top)),width:snap(parseFloat(b.style.width)),height:snap(parseFloat(b.style.height))});
 const update=()=>{const o={};root.querySelectorAll('.field-box').forEach(b=>o[b.dataset.field]=read(b));input.value=JSON.stringify(o);};
 const move=e=>{const s=e.currentTarget._alignment,r=canvas.getBoundingClientRect(),dx=(e.clientX-s.x)/r.width*100,dy=(e.clientY-s.y)/r.height*100;if(s.resize){s.box.style.width=`${snap(clamp(s.w+dx,2,100-s.left))}%`;s.box.style.height=`${snap(clamp(s.h+dy,2,100-s.top))}%`;}else{s.box.style.left=`${snap(clamp(s.left+dx,0,100-parseFloat(s.box.style.width)))}%`;s.box.style.top=`${snap(clamp(s.top+dy,0,100-parseFloat(s.box.style.height)))}%`;}};
 const end=e=>{const b=e.currentTarget;b.releasePointerCapture?.(e.pointerId);b.removeEventListener('pointermove',move);b.removeEventListener('pointerup',end);b.removeEventListener('pointercancel',end);delete b._alignment;update();};
 const bind=b=>{b.addEventListener('pointerdown',e=>{if(e.target.closest('[data-resize-handle]'))return;e.preventDefault();b.setPointerCapture(e.pointerId);b._alignment={box:b,x:e.clientX,y:e.clientY,left:parseFloat(b.style.left),top:parseFloat(b.style.top),w:parseFloat(b.style.width),h:parseFloat(b.style.height),resize:false};b.addEventListener('pointermove',move);b.addEventListener('pointerup',end);b.addEventListener('pointercancel',end);});b.querySelector('[data-resize-handle]').addEventListener('pointerdown',e=>{e.stopPropagation();e.preventDefault();b.setPointerCapture(e.pointerId);b._alignment={box:b,x:e.clientX,y:e.clientY,left:parseFloat(b.style.left),top:parseFloat(b.style.top),w:parseFloat(b.style.width),h:parseFloat(b.style.height),resize:true};b.addEventListener('pointermove',move);b.addEventListener('pointerup',end);b.addEventListener('pointercancel',end);});};
 const add=field=>{if(root.querySelector(`.field-box[data-field="${field}"]`))return;const p=defaults[field],b=document.createElement('div');b.className='field-box absolute cursor-move border-2 border-dashed border-primary bg-transparent hover:bg-primary/5 hover:border-solid text-[10px] leading-tight text-primary-dark';b.dataset.field=field;b.tabIndex=0;b.style.cssText=`left:${p.x}%;top:${p.y}%;width:${p.width}%;height:${p.height}%;`;b.innerHTML=`<span class="rounded bg-white/90 px-1">${labels[field]}</span><div class="resize-handle absolute bottom-0 right-0 h-3 w-3 cursor-se-resize bg-primary" data-resize-handle></div>`;canvas.appendChild(b);bind(b);};
 const remove=field=>root.querySelector(`.field-box[data-field="${field}"]`)?.remove();
 const syncCheckboxesToCanvas=()=>{(root.closest('form')||document).querySelectorAll('.field-toggle').forEach(cb=>{cb.checked?add(cb.dataset.field):remove(cb.dataset.field);});update();};
 (root.closest('form') || document).querySelectorAll('.field-toggle').forEach(cb=>{cb.addEventListener('change',e=>{e.target.checked?add(e.target.dataset.field):remove(e.target.dataset.field);update();});});
 const imageInput=(root.closest('form') || document).querySelector('input[name="background_image"]');
 imageInput?.addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{let image=canvas.querySelector('[data-canvas-image]');if(!image){image=document.createElement('img');image.dataset.canvasImage='';image.className='absolute inset-0 h-full w-full object-fill';canvas.querySelector('[data-canvas-placeholder]')?.remove();canvas.prepend(image);}image.src=reader.result;setReady(true);syncCheckboxesToCanvas();};reader.readAsDataURL(file);});
 setReady(canvas.dataset.imageReady === 'true'); root.querySelectorAll('.field-box').forEach(bind); syncCheckboxesToCanvas();root.querySelector('[data-reset-positions]').addEventListener('click',()=>{root.querySelectorAll('.field-box').forEach(b=>{const p=defaults[b.dataset.field];b.style.left=`${p.x}%`;b.style.top=`${p.y}%`;b.style.width=`${p.width}%`;b.style.height=`${p.height}%`;});update();});root.querySelector('[data-toggle-labels]').addEventListener('click',e=>{const hidden=root.classList.toggle('labels-hidden');e.currentTarget.textContent=`Show labels: ${hidden?'OFF':'ON'}`;root.querySelectorAll('.field-box > span:first-child').forEach(label=>label.classList.toggle('hidden',hidden));});update();
}));
</script>
@endpush
